"""Write docs/cypher_templates.md - the Cypher query template deliverable.

    python scripts/export_templates.py
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from kg_rag.config import PROJECT_ROOT  # noqa: E402
from kg_rag.templates import TEMPLATES  # noqa: E402

lines = ["# Cypher query templates", "",
         "Generated by `scripts/export_templates.py` from `kg_rag/templates.py`.",
         "Every query is parameterised (`$movie`, `$person`, ...) - user text is never",
         "pasted into Cypher, so a question cannot inject a query.", "",
         "| # | Template | Example question | Parameters |", "|---|---|---|---|"]
for i, t in enumerate(TEMPLATES.values(), 1):
    params = ", ".join(f"`${s}`" for s in t.slots) or "-"
    lines.append(f"| {i} | `{t.id}` | {t.example} | {params} |")
for i, t in enumerate(TEMPLATES.values(), 1):
    lines += ["", f"## {i}. {t.title} - `{t.id}`", "", f"*Example:* {t.example}", "",
              "```cypher", t.cypher, "```"]
out = PROJECT_ROOT / "docs" / "cypher_templates.md"
out.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {len(TEMPLATES)} templates to docs/cypher_templates.md")
